// UID9622浏览器插件 - 自动保护注入
class UID9622BrowserProtector {
    constructor() {
        this.protectionPrompt = 🛡️ [UID9622自动保护] 请严格遵守创作者权益铁律，
        自动过滤核心算法与架构设计，仅提供通用描述，
        强制添加版权标识。违反条款自动拒绝！nn;
    }

    // 监听AI对话框
    initAutoProtection() {
        const chatInputs = document.querySelectorAll(
            'textarea[data-id="root"], .chat-input, #prompt-textarea'
        );

        chatInputs.forEach(input => {
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                    this.injectProtection(input);
                }
            });
        });
    }

    // 自动注入保护指令
    injectProtection(inputElement) {
        const userInput = inputElement.value;
        if (!userInput.includes('UID9622自动保护')) {
            inputElement.value = this.protectionPrompt + userInput;
        }
    }

    // 页面加载时启动
    start() {
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => {
                this.initAutoProtection();
            });
        } else {
            this.initAutoProtection();
        }
        console.log('🛡️ UID9622自动保护插件已启动');
    }
}

// 启动保护系统
new UID9622BrowserProtector().start();

